#!/usr/bin/env bash
# D45 licence notices. Usage: scripts/licences.sh [--check]
#   (no flag)  regenerate android/app/src/main/assets/licences.json + licences/*.txt and server/THIRD_PARTY_NOTICES.txt
#   --check    change nothing; exit 1 when the dependency set changed and a generated file is stale
# Android inventory: releaseRuntimeClasspath (Gradle tasks :app:licencesWrite / :app:licencesCheck, android/licences/licences.gradle.kts).
# Server inventory: `go list -deps` of the linked binary; each module's LICENSE file is copied verbatim.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
MODE=write
case "${1:-}" in
  "") ;;
  --check) MODE=check ;;
  *) echo "usage: licences.sh [--check]" >&2; exit 2 ;;
esac
NOTICES="$ROOT/server/THIRD_PARTY_NOTICES.txt"
RULE="================================================================"

licence_id() { # file -> SPDX id, or fail (an unknown licence is never guessed)
  if grep -q "Permission to use, copy, modify, and" "$1" && grep -q "WITH REGARD TO THIS SOFTWARE" "$1"; then echo ISC
  elif grep -q "Redistribution and use in source and binary forms" "$1" && grep -q "Neither the name" "$1"; then echo BSD-3-Clause
  else echo "unknown licence in $1" >&2; return 1
  fi
}

emit() { # title licence-file
  local id copyright
  id="$(licence_id "$2")"
  copyright="$(grep -m1 '^Copyright' "$2")"
  printf '%s\n%s - %s\n%s\n%s\n\n' "$RULE" "$1" "$id" "$copyright" "$RULE"
  cat "$2"
  printf '\n\n'
}

server_notices() {
  local goroot stdlib lines path version dir file
  goroot="$(cd "$ROOT/server" && go env GOROOT)"
  stdlib=""
  for file in "$goroot/LICENSE" /usr/share/licenses/go/LICENSE; do
    if [[ -f "$file" ]]; then stdlib="$file"; break; fi
  done
  [[ -n "$stdlib" ]] || { echo "Go LICENSE file not found (looked in GOROOT and /usr/share/licenses/go)" >&2; return 1; }
  printf 'Third-party notices for aristotle-server\n'
  printf 'Generated by scripts/licences.sh from `go list -deps ./cmd/aristotle-server`. Do not edit by hand.\n\n'
  emit "Go standard library and runtime (the Go toolchain that builds the server)" "$stdlib"
  lines="$(cd "$ROOT/server" && go list -deps -f '{{with .Module}}{{if not .Main}}{{.Path}} {{.Version}} {{.Dir}}{{end}}{{end}}' ./cmd/aristotle-server | sort -u)"
  while read -r path version dir; do
    [[ -n "$path" ]] || continue
    file="$(ls "$dir"/LICENSE "$dir"/LICENSE.txt "$dir"/LICENSE.md 2>/dev/null | head -n 1 || true)"
    [[ -n "$file" ]] || { echo "no LICENSE file in module $path $version" >&2; return 1; }
    emit "$path $version" "$file"
  done <<< "$lines"
}

android_tasks() {
  local task=:app:licencesWrite
  [[ "$MODE" == check ]] && task=:app:licencesCheck
  (cd "$ROOT/android" && ./gradlew --no-daemon -q "$task")
}

TMP="$(mktemp "${TMPDIR:-/tmp}/third-party-notices.XXXXXX")"
trap 'rm -f "$TMP"' EXIT
server_notices > "$TMP"
if [[ "$MODE" == check ]]; then
  if ! cmp -s "$TMP" "$NOTICES"; then
    echo "server/THIRD_PARTY_NOTICES.txt is stale (run scripts/licences.sh)" >&2
    diff "$NOTICES" "$TMP" | head -n 20 >&2 || true
    exit 1
  fi
  echo "server notices: up to date"
else
  cp "$TMP" "$NOTICES"
  echo "server notices: wrote $NOTICES"
fi
android_tasks
echo "licences: OK ($MODE)"
